// time of bar:beat (1-based beat, fractional ok: interpolates between tracked beats)
export function bb(bar, beat = 1) {
  const i = BEATS.findIndex((b) => b[1] === bar && b[2] === Math.floor(beat));
  if (i < 0) throw new Error('beat not in grid: ' + bar + ':' + beat);
  const f = beat - Math.floor(beat);
  return f ? BEATS[i][0] + f * (BEATS[i + 1][0] - BEATS[i][0]) : BEATS[i][0];
}
// fractional beat index at song time s (for beat-synced motion)
export function beatPos(s) {
  let i = 0; while (i < BEATS.length - 2 && BEATS[i + 1][0] <= s) i++;
  return i + (s - BEATS[i][0]) / (BEATS[i + 1][0] - BEATS[i][0]);
}
export function beatTime(k) { // inverse of beatPos (k fractional)
  const i = Math.max(0, Math.min(BEATS.length - 2, Math.floor(k)));
  return BEATS[i][0] + (k - i) * (BEATS[i + 1][0] - BEATS[i][0]);
}
